// Catalog rules, coverage, tint masks and cloth metadata are preserved; no DOM or game UI.
import * as THREE from 'three';
import { characterMeshes, bindToSkeleton } from './vendor/cc/character.js';
import { resolveOutfit, hiddenZoneMask, coveringZoneMask, filterIndex, collidesAsLayer,
  outfitWithUnderwear, layerHiddenZoneMask } from './vendor/cc/clothing_rules.js';

function upgradeCloth(material, mask) {
  const u = {
    ccSecondary: { value: new THREE.Color(1, 1, 1) }, ccMask: { value: mask },
    ccLining: { value: Math.min(1, Math.max(0, Number(material.userData?.tint?.lining) || 0)) },
  };
  material.userData.ccUniforms = u;
  if (mask) {
    mask.colorSpace = THREE.NoColorSpace;
    material.onBeforeCompile = shader => {
      Object.assign(shader.uniforms, u);
      shader.fragmentShader = 'uniform vec3 ccSecondary;\nuniform sampler2D ccMask;\nuniform float ccLining;\n' + shader.fragmentShader.replace(
        '#include <map_fragment>', `#include <map_fragment>
#ifdef USE_MAP
  float ccM = texture2D(ccMask, vMapUv).r;
  if (!gl_FrontFacing) ccM = max(ccM, ccLining);
  diffuseColor.rgb = mix(diffuseColor.rgb, sampledDiffuseColor.rgb * ccSecondary, ccM);
#endif`);
    };
    material.customProgramCacheKey = () => 'ccClothMask';
  }
  material.side = THREE.DoubleSide;
  material.needsUpdate = true;
}

export function createClothing({ loader, body, parts, lifetime, owner, getSex, onChange }) {
  const cache = new Map(), pending = new Map(), colors = {};
  let catalog = null, worn = [], token = 0;
  const bodyIndex = body.geometry.index?.array.slice();
  const item = id => catalog?.items.find(it => it.id === id);
  async function load(id) {
    if (cache.has(id)) return cache.get(id);
    if (pending.has(id)) return pending.get(id);
    const promise = (async () => {
      const it = item(id);
      if (!it) throw new Error(`Unknown clothing item: ${id}`);
      const g = await loader.loadAsync(it.file);
      const meshes = characterMeshes(g.scene);
      if (!meshes.length) throw new Error(`${it.file}: no skinned clothing mesh`);
      for (const mesh of meshes) mesh.morphTargetInfluences?.fill(0);
      for (const mesh of meshes) for (const mat of [].concat(mesh.material)) {
        const mi = mat.userData?.ccMask?.index;
        const mask = mi !== undefined ? await lifetime.accept(g.parser.getDependency('texture', mi), texture => owner.own(texture)) : null;
        if (mask) owner.own(mask);
        upgradeCloth(mat, mask);
        owner.refresh();
        lifetime.assertAlive();
      }
      for (const mesh of meshes) {
        lifetime.assertAlive();
        mesh.removeFromParent();
        mesh.position.copy(body.position); mesh.quaternion.copy(body.quaternion); mesh.scale.copy(body.scale);
        const binding = bindToSkeleton(mesh, body.skeleton, body.bindMatrix);
        if (binding.missing.length) throw new Error(`${it.file}: missing body bones`);
        body.parent.add(mesh);
        mesh.frustumCulled = false; mesh.visible = false;
        Object.assign(mesh.userData, { ccClothing: id, ccLayer: it.layer ?? 0, ccLayerCollide: collidesAsLayer(it) });
        parts.push(mesh);
      }
      cache.set(id, meshes);
      return meshes;
    })();
    pending.set(id, promise);
    try { return await promise; } finally { pending.delete(id); }
  }
  function setColor(id, which, hex) {
    lifetime.assertAlive();
    if (!colors[id]) return;
    colors[id][which] = hex;
    for (const mesh of cache.get(id) || []) for (const mat of [].concat(mesh.material)) {
      const gain = Number(mat.userData?.tint?.gain) > 0 ? Number(mat.userData.tint.gain) : 1;
      if (which === 'primary') mat.color.set(hex).multiplyScalar(gain);
      else mat.userData.ccUniforms?.ccSecondary.value.set(hex).multiplyScalar(gain);
    }
  }
  function zones() {
    const attr = body.geometry.attributes[(catalog.bodyZoneAttribute || '_CCZONE').toLowerCase()];
    if (bodyIndex && attr) {
      body.geometry.setIndex(new THREE.BufferAttribute(filterIndex(bodyIndex, attr, hiddenZoneMask(catalog, worn)), 1));
      body.userData.ccLayerIndex = filterIndex(bodyIndex, attr, layerHiddenZoneMask(catalog, worn));
    }
    for (const id of worn) for (const mesh of cache.get(id) || []) {
      const geo = mesh.geometry, attr = geo.attributes._cczone;
      if (!attr || !geo.index) continue;
      mesh.userData.ccIndex ??= geo.index.array.slice();
      const index = filterIndex(mesh.userData.ccIndex, attr, coveringZoneMask(catalog, worn, id));
      geo.setIndex(new THREE.BufferAttribute(index, 1));
      mesh.userData.ccCovered = index.length === 0;
      if (!index.length) mesh.visible = false;
    }
  }
  async function setOutfit(ids) {
    lifetime.assertAlive();
    if (!catalog) throw new Error('Clothing catalog is not ready');
    const list = typeof ids === 'string' ? ids.split(',') : ids;
    for (const id of list || []) if (id !== 'none' && !item(id)) throw new Error(`Unknown clothing item: ${id}`);
    const want = resolveOutfit(catalog, outfitWithUnderwear(catalog, list, getSex(), true));
    const mine = ++token;
    await Promise.all(want.map(load));
    lifetime.assertAlive();
    if (mine !== token) return;
    worn = want;
    for (const [id, meshes] of cache) {
      for (const mesh of meshes) mesh.visible = worn.includes(id);
      if (worn.includes(id)) {
        setColor(id, 'primary', colors[id].primary);
        if (colors[id].secondary) setColor(id, 'secondary', colors[id].secondary);
      }
    }
    zones(); onChange();
  }
  return {
    async init(manifest, initial) {
      catalog = await manifest;
      lifetime.assertAlive();
      if (!catalog?.items?.length) throw new Error('Missing or invalid clothing.json');
      for (const it of catalog.items) colors[it.id] = { primary: it.colors?.primary ?? '#808080', secondary: it.colors?.secondary ?? null };
      await setOutfit(initial);
    },
    setOutfit, setColor, worn: () => [...worn],
    get catalog() { return catalog; },
    dispose() { token++; cache.clear(); },
  };
}
